class Solution:
    def minTime(self, n, edges):
        import heapq
        from collections import defaultdict
        g = defaultdict(list)
        for u, v, s, e in edges:
            g[u].append((v, s, e))
        INF = float('inf')
        dist = [INF] * n; dist[0] = 0
        pq = [(0, 0)]
        while pq:
            d, u = heapq.heappop(pq)
            if u == n - 1: return d
            if d > dist[u]: continue
            for v, s, e in g[u]:
                if d <= e:
                    nd = max(d, s) + 1
                    if nd < dist[v]:
                        dist[v] = nd
                        heapq.heappush(pq, (nd, v))
        return -1

