class Solution {
    public int minTime(int n, int[][] edges) {
        List<int[]>[] g = new List[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int[] e : edges) g[e[0]].add(new int[]{e[1], e[2], e[3]});
        long[] dist = new long[n]; Arrays.fill(dist, Long.MAX_VALUE); dist[0] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.add(new long[]{0, 0});
        while (!pq.isEmpty()) {
            long[] top = pq.poll(); long d = top[0]; int u = (int) top[1];
            if (u == n - 1) return (int) d;
            if (d > dist[u]) continue;
            for (int[] ed : g[u]) {
                if (d <= ed[2]) {
                    long nd = Math.max(d, ed[1]) + 1;
                    if (nd < dist[ed[0]]) { dist[ed[0]] = nd; pq.add(new long[]{nd, ed[0]}); }
                }
            }
        }
        return -1;
    }
}

