var minTime = function(n, edges) {
    const g = Array.from({length: n}, () => []);
    for (const [u, v, s, e] of edges) g[u].push([v, s, e]);
    const dist = new Array(n).fill(Infinity); dist[0] = 0;
    const pq = [[0, 0]];
    const push = (x) => { pq.push(x); let i = pq.length - 1;
        while (i > 0) { const p = (i-1)>>1; if (pq[p][0] <= pq[i][0]) break; [pq[p],pq[i]]=[pq[i],pq[p]]; i = p; } };
    const pop = () => { const t = pq[0], l = pq.pop(); if (pq.length) { pq[0] = l; let i = 0;
        for (;;) { let a = 2*i+1, b = a+1, m = i; if (a < pq.length && pq[a][0] < pq[m][0]) m = a; if (b < pq.length && pq[b][0] < pq[m][0]) m = b; if (m === i) break; [pq[m],pq[i]]=[pq[i],pq[m]]; i = m; } } return t; };
    while (pq.length) {
        const [d, u] = pop();
        if (u === n - 1) return d;
        if (d > dist[u]) continue;
        for (const [v, s, e] of g[u]) {
            if (d <= e) {
                const nd = Math.max(d, s) + 1;
                if (nd < dist[v]) { dist[v] = nd; push([nd, v]); }
            }
        }
    }
    return -1;
};
